def retry_with_backoff(func):
    """Simple retry decorator with exponential backoff."""
    import time
    import functools

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        delay = 0.1
        max_delay = 5.0
        while True:
            try:
                return func(*args, **kwargs)
            except Exception as e:
                if delay > max_delay:
                    raise e
                time.sleep(delay)
                delay *= 2
    return wrapper

