import time

def chunked(items, size):
    for i in range(0, len(items), size):
        yield items[i:i + size]

def retry_with_backoff(func):
    def wrapper(*args, **kwargs):
        max_retries = 3
        base_delay = 1
        for i in range(max_retries):
            try:
                return func(*args, **kwargs)
            except Exception:
                if i == max_retries - 1:
                    raise
                time.sleep(base_delay * (2 ** i))
    return wrapper

