import os
import shutil

def delete_junk(root):
    junk_extensions = {'.pyc', '.pyo', '.log', '.tmp', '.bak', '.swp'}
    junk_names = {'__pycache__', '.pytest_cache', '.coverage', 'Thumbs.db', '.DS_Store'}
    for dirpath, dirnames, filenames in os.walk(root, topdown=False):
        # Delete junk files
        for f in filenames:
            if any(f.endswith(ext) for ext in junk_extensions) or f in junk_names:
                os.remove(os.path.join(dirpath, f))
                print(f'Removed file: {os.path.join(dirpath, f)}')
        # Delete junk directories
        for d in dirnames:
            if d in junk_names:
                shutil.rmtree(os.path.join(dirpath, d))
                print(f'Removed directory: {os.path.join(dirpath, d)}')

if __name__ == '__main__':
    delete_junk('.')

